begin;
set local lock_timeout = '30s';

-- GENERATED by scripts/gen-migrations.mjs from supabase/templates. Do not edit by hand.
-- Gate 15: advisory contract (Res. CVM 19), recommendations log, KYC/PLD fields (Res. CVM 50), CVM export (D-049). Additive.

-- ---------------------------------------------------------------- KYC / PLD (Res. CVM 50)
alter table cw_nonprod.client_personal_data
  add column is_pep boolean,                                -- pessoa exposta politicamente
  add column pep_related boolean,                           -- familiar ou estreito colaborador de PEP
  add column pep_detail text check (length(pep_detail) <= 500),
  add column funds_sources text[] check (funds_sources <@ array['SALARY', 'BUSINESS', 'INVESTMENTS', 'INHERITANCE', 'ASSET_SALE', 'RETIREMENT', 'OTHER']),
  add column funds_detail text check (length(funds_detail) <= 1000),
  add column us_person boolean;                             -- FATCA

create function cw_nonprod.registry_save_kyc(p_client uuid, p_data jsonb) returns void
language plpgsql security definer set search_path = '' as $$
begin
  perform cw_nonprod_private.require_client(p_client);
  if not exists (select 1 from cw_nonprod.client_personal_data where client_id = p_client) then
    raise exception 'personal data first' using errcode = '22023';
  end if;
  update cw_nonprod.client_personal_data set
    is_pep = (p_data ->> 'is_pep')::boolean, pep_related = (p_data ->> 'pep_related')::boolean,
    pep_detail = nullif(btrim(p_data ->> 'pep_detail'), ''),
    funds_sources = coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(p_data -> 'funds_sources', '[]'::jsonb)) x), '{}'),
    funds_detail = nullif(btrim(p_data ->> 'funds_detail'), ''), us_person = (p_data ->> 'us_person')::boolean
   where client_id = p_client;
end $$;

-- ---------------------------------------------------------------- recommendations (kept with the profile in force)
alter type cw_nonprod.crm_activity_kind add value if not exists 'RECOMMENDATION';
alter table cw_nonprod.crm_activities
  add column channel text check (channel in ('MEETING', 'EMAIL', 'WHATSAPP', 'CALL', 'REPORT', 'OTHER')),
  add column profile_at_time text check (profile_at_time in ('CONSERVADOR', 'MODERADO', 'ARROJADO', 'NONE'));

create function cw_nonprod.crm_recommendation_add(p_contact uuid, p_channel text, p_occurred_at timestamptz, p_summary text, p_rationale text)
returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid; v_client uuid; v_profile text;
begin
  if not cw_nonprod_private.is_staff() then perform cw_nonprod_private.deny(); end if;
  perform cw_nonprod_private.require_contact(p_contact);
  select client_id into v_client from cw_nonprod.crm_contacts where id = p_contact;
  select profile into v_profile from cw_nonprod.suitability_assessments where client_id = v_client order by confirmed_at desc limit 1;
  insert into cw_nonprod.crm_activities (contact_id, kind, occurred_at, owner_id, summary, outcome, channel, profile_at_time)
  values (p_contact, 'RECOMMENDATION', coalesce(p_occurred_at, now()), auth.uid(), btrim(p_summary), nullif(btrim(p_rationale), ''),
          p_channel, coalesce(v_profile, 'NONE'))
  returning id into v_id;
  return v_id;
end $$;

-- ---------------------------------------------------------------- advisory contract
alter table cw_nonprod.cvm_settings
  add column contract_template text check (length(contract_template) <= 40000),
  add column firm_name text check (length(firm_name) <= 160),
  add column firm_document text check (length(firm_document) <= 30),
  add column advisor_registration text check (length(advisor_registration) <= 60),
  add column firm_address text check (length(firm_address) <= 300),
  add column firm_city text check (length(firm_city) <= 80);

create table cw_nonprod.client_contracts (
  id                 uuid primary key default gen_random_uuid(),
  client_id          uuid not null references cw_nonprod.clients (id) on delete cascade,
  fee_rate_pct       numeric(7,4) not null check (fee_rate_pct >= 0 and fee_rate_pct <= 100),
  variables          jsonb not null default '{}' check (jsonb_typeof(variables) = 'object' and length(variables::text) <= 8000),
  special_conditions text check (length(special_conditions) <= 6000),
  body               text not null check (length(body) between 50 and 60000),   -- rendered text: what was downloaded
  status             text not null default 'ISSUED' check (status in ('ISSUED', 'SIGNED', 'CANCELLED')),
  signed_on          date,
  signature_note     text check (length(signature_note) <= 300),
  created_by         uuid not null references cw_nonprod.profiles (id),
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  check ((status = 'SIGNED') = (signed_on is not null))
);
create index on cw_nonprod.client_contracts (client_id, created_at desc);
alter table cw_nonprod.client_contracts enable row level security;
alter table cw_nonprod.client_contracts force row level security;
create policy client_contracts_read on cw_nonprod.client_contracts for select to authenticated using ((select cw_nonprod_private.can_access_client(client_id)));
revoke all on cw_nonprod.client_contracts from public, anon, authenticated;
grant select on cw_nonprod.client_contracts to authenticated;
grant all on cw_nonprod.client_contracts to service_role;
create trigger t_audit after insert or update or delete on cw_nonprod.client_contracts for each row execute function cw_nonprod_private.audit_row();

create function cw_nonprod.cvm_settings_save_contract(p_template text, p_firm jsonb) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if not cw_nonprod_private.is_staff() then perform cw_nonprod_private.deny(); end if;
  insert into cw_nonprod.cvm_settings (owner_id, contract_template, firm_name, firm_document, advisor_registration, firm_address, firm_city)
  values (auth.uid(), nullif(btrim(p_template), ''), nullif(btrim(p_firm ->> 'firm_name'), ''), nullif(btrim(p_firm ->> 'firm_document'), ''),
          nullif(btrim(p_firm ->> 'advisor_registration'), ''), nullif(btrim(p_firm ->> 'firm_address'), ''), nullif(btrim(p_firm ->> 'firm_city'), ''))
  on conflict (owner_id) do update set contract_template = excluded.contract_template, firm_name = excluded.firm_name,
    firm_document = excluded.firm_document, advisor_registration = excluded.advisor_registration, firm_address = excluded.firm_address,
    firm_city = excluded.firm_city, updated_at = now();
end $$;

-- The server renders the text; the database keeps exactly what was issued.
create function cw_nonprod.client_contract_issue(p_client uuid, p_fee numeric, p_variables jsonb, p_special text, p_body text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare v_id uuid;
begin
  if not cw_nonprod_private.is_staff() then perform cw_nonprod_private.deny(); end if;
  perform cw_nonprod_private.require_client(p_client);
  insert into cw_nonprod.client_contracts (client_id, fee_rate_pct, variables, special_conditions, body, created_by)
  values (p_client, p_fee, coalesce(p_variables, '{}'), nullif(btrim(p_special), ''), p_body, auth.uid())
  returning id into v_id;
  return v_id;
end $$;

create function cw_nonprod.client_contract_set_status(p_id uuid, p_status text, p_signed_on date, p_note text) returns void
language plpgsql security definer set search_path = '' as $$
declare v_client uuid; v_status text;
begin
  if not cw_nonprod_private.is_staff() then perform cw_nonprod_private.deny(); end if;
  select client_id, status into v_client, v_status from cw_nonprod.client_contracts where id = p_id for update;
  perform cw_nonprod_private.require_client(v_client);
  if v_status <> 'ISSUED' or p_status not in ('SIGNED', 'CANCELLED') then raise exception 'invalid transition' using errcode = '22023'; end if;
  update cw_nonprod.client_contracts
     set status = p_status, signed_on = case when p_status = 'SIGNED' then coalesce(p_signed_on, current_date) end,
         signature_note = nullif(btrim(p_note), ''), updated_at = now()
   where id = p_id;
end $$;

revoke all on function cw_nonprod.registry_save_kyc(uuid, jsonb), cw_nonprod.crm_recommendation_add(uuid, text, timestamptz, text, text),
  cw_nonprod.cvm_settings_save_contract(text, jsonb), cw_nonprod.client_contract_issue(uuid, numeric, jsonb, text, text),
  cw_nonprod.client_contract_set_status(uuid, text, date, text) from public, anon, authenticated;
grant execute on function cw_nonprod.registry_save_kyc(uuid, jsonb), cw_nonprod.crm_recommendation_add(uuid, text, timestamptz, text, text),
  cw_nonprod.cvm_settings_save_contract(text, jsonb), cw_nonprod.client_contract_issue(uuid, numeric, jsonb, text, text),
  cw_nonprod.client_contract_set_status(uuid, text, date, text) to authenticated;

commit;

select 'migração 24 ok' as resultado, count(*) as tabelas_protegidas from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='cw_nonprod' and c.relforcerowsecurity and c.relname = 'client_contracts';
